function possibleStringCount(word) {
  let count = 1;
  let start = 0;
  while (start < word.length) {
    let end = start;
    while (end < word.length && word[end] === word[start]) {
      end++;
    }
    count += end - start - 1;
    start = end;
  }
  return count;
}

