function possibleStringCount(word) {
  // Undo every possible long press: k >= 2 equal letters starting at p shrink back to one letter.
  const originals = new Set([word]);
  for (let p = 0; p < word.length; p++) {
    for (let k = 2; p + k <= word.length; k++) {
      if (word.slice(p, p + k) === word[p].repeat(k)) originals.add(word.slice(0, p) + word[p] + word.slice(p + k));
    }
  }
  return originals.size;
}

