function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  // Few distinct letters make long blocks of equal letters likely.
  const letters = size === 'large' ? [1, 2, 3, 26][Math.floor(rand() * 4)] : 1 + Math.floor(rand() * 3);
  const base = Math.floor(rand() * (27 - letters));
  let word = '';
  for (let i = 0; i < n; i++) word += String.fromCharCode(97 + base + Math.floor(rand() * letters));
  return [word];
}
